#!/usr/bin/env python3
"""Source-driven about page. Existing site shell; stdlib, local SVG, no network."""
from pathlib import Path
import json,re,html,datetime
ROOT=Path(__file__).resolve().parents[1]
def facts(arts=None):
 if arts is None:
  now=datetime.datetime.now(datetime.timezone.utc)
  arts=[a for p in (ROOT/'content/articles').glob('*.json') if (a:=json.loads(p.read_text())) and datetime.datetime.fromisoformat(a['published'].replace('Z','+00:00'))<=now]
 legacy=json.loads((ROOT/'content/home-legacy.json').read_text());portraits=json.loads((ROOT/'content/portraits.json').read_text())
 return {'analyses':len({a['slug'] for a in arts}|{a['slug'] for a in legacy}), 'new':len(arts),'legacy':len(legacy),'companies':len(portraits['companies']),'models':len(portraits['models']),'benchmarks':len(portraits['benchmarks']),'glossary':len(json.loads((ROOT/'content/glossary.json').read_text()))}
def render(arts=None):
 f=facts(arts);maximum=max(f[k] for k in ['analyses','companies','models','benchmarks','glossary']) or 1;p=ROOT/'ueber.html';s=p.read_text();stamp=datetime.datetime.now().strftime('%d.%m.%Y')
 tiles=''.join('<a class="ab-stat" href="%s"><strong>%s</strong><span>%s</span><small>%s ↗</small></a>'%(url,f[key],label,note) for key,label,url,note in [('analyses','Analysen & Grundlagen','/#themen','Beiträge lesen'),('companies','Unternehmensporträts','/unternehmen','Anbieter einordnen'),('models','Modellporträts','/ki-modelle','Modelle verstehen'),('benchmarks','Benchmark-Porträts','/benchmarks','Messmethoden prüfen'),('glossary','Glossarbegriffe','/glossar','Begriffe nachschlagen')])
 bars=''.join('<g transform="translate(0,%s)"><text x="0" y="16">%s</text><rect x="0" y="29" width="420" height="12" rx="3" fill="#efebf6"/><rect x="0" y="29" width="%.2f" height="12" rx="3" fill="#7040cd"/><text x="440" y="40">%s</text></g>'%(i*68,label,f[k]/maximum*420,f[k]) for i,(k,label) in enumerate([('analyses','Analysen & Grundlagen'),('companies','Unternehmen'),('models','KI-Modelle'),('benchmarks','Benchmarks'),('glossary','Glossarbegriffe')]))
 inventory='<svg viewBox="0 0 500 370" role="img" aria-label="Umfang des Angebots: '+', '.join(str(f[k])+' '+l for k,l in [('analyses','Beiträge'),('companies','Unternehmen'),('models','Modelle'),('benchmarks','Benchmarks'),('glossary','Glossarbegriffe')])+'"><title>Der Inhalt des KI Fachblatts in Zahlen</title>'+bars+'<text x="0" y="365">0</text><text x="420" y="365" text-anchor="end">'+str(maximum)+' Einträge</text></svg>'
 process='<svg viewBox="0 0 680 110" role="img" aria-label="Redaktioneller Ablauf: Recherche, Prüfung, Veröffentlichung, danach Korrekturen bei Bedarf"><title>Von der Quelle zum Beitrag</title><path d="M50 38H630" stroke="#d8c8ef" stroke-width="2"/>'+''.join('<circle cx="%d" cy="38" r="22" fill="#7040cd"/><text x="%d" y="44" text-anchor="middle" fill="white">%s</text><text x="%d" y="88" text-anchor="middle" fill="#151519">%s</text>'%(x,x,i,x,l) for x,i,l in [(75,'01','Recherche'),(250,'02','Prüfung'),(425,'03','Veröffentlichung'),(600,'04','Korrekturen')])+'</svg>'
 config=json.loads((ROOT/'content/monetization.json').read_text());inactive=not config['advertising']['enabled'] and not config['analytics']['enabled']
 ads='Statistik- und Werbedienste sind in der aktuellen Website-Konfiguration deaktiviert. Die technischen Vorbereitungen für Werbung sind vorhanden, aber nicht freigeschaltet.' if inactive else 'Den aktuellen Status von Statistik- und Werbediensten findest du in den Datenschutzeinstellungen und in den Hinweisen zu Werbung.'
 inner='''<main id="main" class="about-page"><div class="wrap">
<section class="ab-hero"><div><p class="ab-kicker">Über das KI Fachblatt</p><h1>Einordnen.<br>Nachrechnen.<br>Verstehen.</h1><p class="ab-lead">Ein deutschsprachiges Fachmagazin über künstliche Intelligenz. Für Menschen, die Modelle, Agenten und Werkzeuge nicht nur nutzen, sondern ihre Möglichkeiten und Grenzen verstehen wollen.</p><a class="ab-action" href="/#themen">Die Analysen lesen ↗</a></div><aside class="ab-manifest"><span class="ab-kicker">Unser Maßstab</span><p>Die Quelle zählt.<br>Die Methode auch.</p><div>Herstellerangaben sind keine unabhängigen Tests. Ein Trend-Score ist kein Qualitätsurteil. Eine eigene Rechnung braucht eine nachvollziehbare Grundlage.</div><a href="/quellen">Quellen und Faktencheck ↗</a></aside></section>
<section aria-labelledby="ab-counts"><div class="ab-section-title"><div><p class="ab-kicker">Das Angebot in Zahlen</p><h2 id="ab-counts">Wissen, das zusammenhängt.</h2></div><p>Inhaltsbestand · '''+stamp+'''<br>Keine Reichweiten- oder Erfolgszahlen.</p></div><div class="ab-stats">'''+tiles+'''</div><p class="ab-note">Automatisch aus dem veröffentlichten Inhaltsbestand gezählt: '''+str(f['new'])+''' aktuelle Analysen und '''+str(f['legacy'])+''' ältere Grundlagenbeiträge. Porträts und Glossarbegriffe werden getrennt gezählt; die Kategorien sind keine Qualitätsbewertung.</p></section>
<section class="ab-split"><div class="ab-visual"><p class="ab-kicker">Eine Bestandsaufnahme</p><h2>Von der Analyse zum Begriff.</h2>'''+inventory+'''<p class="ab-note">Anzahl je Inhaltsart, gemeinsame Skala ab null. Unterschiedliche Formate, nicht addierte Leserzahlen.</p></div><div class="ab-copy"><p class="ab-kicker">Vier Zugänge</p><h2>Tiefe statt Schlagzeilen.</h2><ol class="ab-access"><li><h3>Analysen</h3><p>Modelle, Architektur und Evaluation: mit Quellen, eigenen Rechnungen, Methode und Grenzen.</p></li><li><h3>Porträts</h3><p>Unternehmen und Modelle im Zusammenhang. Benchmark-Porträts erklären, was eine Messung aussagt und was nicht.</p></li><li><h3>Glossar</h3><p>Begriffe nachschlagen und über Querverweise weiterdenken.</p></li><li><h3>Tagesbericht</h3><p>Ein automatisch erzeugtes PDF mit Hugging-Face-Trenddaten und den zwei neuesten Analysen. Trend, Likes und Downloads messen Aufmerksamkeit, nicht Modellqualität.</p></li></ol></div></section>
<section class="ab-process"><p class="ab-kicker">So entsteht ein Beitrag</p><h2>Ein nachvollziehbarer Weg.</h2><figure>'''+process+'''<figcaption>Redaktioneller Ablauf laut unseren veröffentlichten Grundsätzen, keine gemessenen Bearbeitungszeiten.</figcaption></figure><div class="ab-steps"><div><b>01 · Recherche</b><p>Primärquellen zuerst: Modellkarten, technische Dokumentation, Papers und Messdaten. Sekundärquellen dienen der Einordnung.</p></div><div><b>02 · Prüfung</b><p>Quelle, Zahl, Datum und Kontext prüfen. Eigene Rechnungen von Herstellerangaben trennen, Unsicherheit benennen.</p></div><div><b>03 · Veröffentlichung</b><p>Quellen und Grenzen sichtbar machen. Philipp Paulik verantwortet Themenauswahl, Quellenprüfung und Veröffentlichung.</p></div><div><b>04 · Korrekturen</b><p>Inhaltliche Fehler im Beitrag berichtigen, Aktualisierungsdatum setzen und die Korrektur vermerken.</p></div></div><a href="/redaktion">Redaktionelle Grundsätze ↗</a></section>
<section class="ab-policies"><article><p class="ab-kicker">Aktualität</p><h2>Ein Datum gehört dazu.</h2><p>Analysen erscheinen ohne fest zugesagte Frequenz. Preise, Versionen und Regeln gelten zum angegebenen Abrufdatum; wichtige Änderungen werden nach unserer Korrekturpolitik eingearbeitet.</p><p>Für den Tagesbericht ist eine tägliche automatische Erstellung um 05:20 UTC eingerichtet. Das ist der geplante Lauf, keine garantierte Lieferzeit. Datenabruf und technische Verfügbarkeit können die Ausgabe beeinflussen.</p><a href="/berichte">Tagesbericht und Archiv ↗</a></article><article><p class="ab-kicker">KI-Transparenz</p><h2>Unterstützung offenlegen.</h2><p>KI-Werkzeuge unterstützen Recherche, Textentwürfe und Illustrationen. Die redaktionelle Verantwortung bleibt bei Philipp Paulik. KI-Illustrationen werden gekennzeichnet; eigene Datengrafiken sind keine fotografischen Belege.</p><p>Unsere veröffentlichten Grundsätze untersagen erfundene Zahlen, Studien und Zitate sowie die Veröffentlichung redaktioneller Beiträge ohne menschliche Freigabe. Der automatische Tagesbericht ist ein gesondertes Datenformat.</p><a href="/transparenz">Die KI-Transparenz im Detail ↗</a></article></section>
<section class="ab-owner"><div><p class="ab-kicker">Verantwortung & Kontakt</p><h2>Ein Magazin von Philipp Paulik.</h2><p>Herausgeber und redaktionell verantwortlich: Philipp Paulik. Angaben zum Anbieter stehen im <a href="/impressum">Impressum</a>, das Autorenprofil unter <a href="/redakteur/philipp-paulik">Redaktion</a>.</p><p>Eine Zahl stimmt nicht, ein Beleg fehlt? Schreib mit dem Beitragstitel und der betreffenden Stelle an <a href="mailto:philipp.l.paulik@gmail.com">philipp.l.paulik@gmail.com</a>.</p><a href="/korrekturen">So gehen wir mit Fehlern um ↗</a></div><aside><h3>Unabhängigkeit & Finanzierung</h3><p>Die redaktionellen Grundsätze sehen eine klare Kennzeichnung bezahlter Inhalte, Anzeigen und Affiliate-Links vor.</p><p>'''+ads+'''</p><p>Stand der Konfiguration: '''+stamp+'''. <a href="/werbung">Werbung & Affiliate</a> · <a href="/datenschutz">Datenschutz</a></p></aside></section>
</div></main>'''
 s=re.sub(r'<main id="main".*?</main>',lambda _:inner,s,count=1,flags=re.S)
 if '/assets/about.css' not in s:s=s.replace('</head>','<link rel="stylesheet" href="/assets/about.css"></head>')
 p.write_text(s);print('about:',f)
if __name__=='__main__':render()
